，夏鲁奇任副招讨，率步骑四万讨荆南", "start_year": 927, "end_year": 927, "time_original": "927年二月壬寅", "dynasty": "五代十国", "description": "刘训任南面招讨兼知荆南行府事，夏鲁奇任副招讨，率步骑四万讨荆南。", "phases": [], "location_name": "山南东道至荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "65af8048-74be-5881-bdb3-eb4cfc693303"}, {"title": "董璋任东南面招讨、西方邺为副，川军下峡并会湖南军三面进攻", "start_year": 927, "end_year": 927, "time_original": "927年二月壬寅讨伐部署", "dynasty": "五代十国", "description": "董璋任东南面招讨、西方邺为副，川军下峡并会湖南军三面进攻。", "phases": [], "location_name": "东川、夔州下峡及湖南至荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f1c3bd10-a2aa-54fa-8f6c-72822b512473"}, {"title": "朝廷任李敬周为武信留后", "start_year": 927, "end_year": 927, "time_original": "927年三月甲寅", "dynasty": "五代十国", "description": "朝廷任李敬周为武信留后。", "phases": [], "location_name": "遂州、武信军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4cc12901-1089-5196-8df8-eeab227955c4"}, {"title": "后唐初置监牧以繁息国马", "start_year": 927, "end_year": 927, "time_original": "927年三月丙辰", "dynasty": "五代十国", "description": "后唐初置监牧以繁息国马。", "phases": [], "location_name": "后唐诸处", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6877489a-c7c7-52f8-b6dd-b6a99651af62"}]'::jsonb)
